require_once __DIR__ . '/config/config.php';
require_login();

define('HERDSIGNAL_DASHBOARD_REQUEST', true);
require_once __DIR__ . '/check_dashboard_reminders.php';
$uid=(int)$_SESSION['user_id'];
$stmt=$conn->prepare("SELECT COUNT(*) c FROM animals WHERE owner_id=? AND status='Active'");$stmt->bind_param('i',$uid);$stmt->execute();$animal_count=(int)$stmt->get_result()->fetch_assoc()['c'];
$stmt=$conn->prepare("SELECT COUNT(*) c FROM reminders WHERE owner_id=? AND status='Pending' AND due_date>=CURDATE()");$stmt->bind_param('i',$uid);$stmt->execute();$upcoming=(int)$stmt->get_result()->fetch_assoc()['c'];
$stmt=$conn->prepare("SELECT COUNT(*) c FROM reminders WHERE owner_id=? AND status='Pending' AND due_date<CURDATE()");$stmt->bind_param('i',$uid);$stmt->execute();$overdue=(int)$stmt->get_result()->fetch_assoc()['c'];
$stmt=$conn->prepare("SELECT COUNT(*) c FROM health_records h JOIN animals a ON a.id=h.animal_id WHERE a.owner_id=?");$stmt->bind_param('i',$uid);$stmt->execute();$health_count=(int)$stmt->get_result()->fetch_assoc()['c'];
$stmt=$conn->prepare("SELECT a.animal_code,a.name,a.species,a.sex,a.status FROM animals a WHERE a.owner_id=? ORDER BY a.created_at DESC LIMIT 5");$stmt->bind_param('i',$uid);$stmt->execute();$animals=$stmt->get_result();
$stmt=$conn->prepare("SELECT r.title,r.due_date,r.status,a.animal_code FROM reminders r LEFT JOIN animals a ON a.id=r.animal_id WHERE r.owner_id=? AND r.status='Pending' ORDER BY r.due_date ASC LIMIT 5");$stmt->bind_param('i',$uid);$stmt->execute();$reminders=$stmt->get_result();
$page_title='Overview';require __DIR__.'/includes/header.php';
